 function propertyArt(key,index){
  const palettes={"estate-luxe":["#E9E0D3","#B99768","#233640","#F7F1E7"],"nestliving-rentals":["#E8E7D9","#B96F55","#2D4A40","#FAF3E9"],"urbanaxis-commercial":["#DCE7EC","#3E7189","#203448","#F3F6F7"],"horizon-developments":["#E1E8E1","#A66B49","#2B4038","#F4F3EF"]};
  const p=palettes[key]||palettes["estate-luxe"],seed=Array.from(key+":"+index).reduce((a,c)=>((a*33)+c.charCodeAt(0))>>>0,5381),h=seed%5+3,w=1200,sky=p[0],accent=p[1],ink=p[2],light=p[3],base=260+(seed%180),building=340+(seed%180),windows=Array.from({length:h*3},(_,i)=>'<rect x="'+(140+(i%3)*95)+'" y="'+(310+Math.floor(i/3)*78)+'" width="44" height="46" rx="3" fill="'+light+'" opacity="'+(0.62+(i%3)*0.1)+'"/>').join("");
  const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 800"><defs><linearGradient id="s" x2="0" y2="1"><stop stop-color="'+sky+'"/><stop offset="1" stop-color="'+light+'"/></linearGradient><linearGradient id="b" x2="1" y2="1"><stop stop-color="'+ink+'"/><stop offset="1" stop-color="'+accent+'"/></linearGradient></defs><rect width="1200" height="800" fill="url(#s)"/><circle cx="'+(930+seed%130)+'" cy="'+(120+seed%90)+'" r="'+(42+seed%32)+'" fill="'+accent+'" opacity=".55"/><path d="M0 590 Q260 540 520 590 T1200 560 V800 H0Z" fill="'+accent+'" opacity=".22"/><rect x="'+(110+seed%70)+'" y="'+(base-building)+'" width="'+(440+seed%100)+'" height="'+(800-base+building-120)+'" rx="10" fill="url(#b)"/>'+windows+'<path d="M'+(95+seed%50)+' '+(base-building)+' l'+(230+seed%40)+' -'+(85+seed%35)+' l'+(260+seed%60)+' '+(85+seed%35)+'Z" fill="'+ink+'"/><rect x="'+(650+seed%70)+'" y="'+(370+seed%80)+'" width="'+(260+seed%90)+'" height="'+(430-seed%70)+'" rx="8" fill="'+ink+'" opacity=".9"/><g fill="'+light+'" opacity=".8">'+Array.from({length:12},(_,i)=>'<rect x="'+(680+(i%3)*72)+'" y="'+(400+Math.floor(i/3)*74)+'" width="42" height="44" rx="2"/>').join("")+'</g><path d="M0 690 Q250 650 480 690 T1200 680" stroke="'+ink+'" stroke-width="5" opacity=".25" fill="none"/><g fill="'+accent+'"><circle cx="'+(1010+seed%80)+'" cy="640" r="50"/><circle cx="'+(1080+seed%60)+'" cy="655" r="38"/></g><g fill="'+ink+'"><rect x="1000" y="650" width="12" height="95"/><rect x="1080" y="660" width="10" height="85"/></g><path d="M0 748 H1200" stroke="'+ink+'" stroke-width="4" opacity=".18"/></svg>';
  return "data:image/svg+xml;charset=UTF-8,"+encodeURIComponent(svg);
 }
