  const section='<section class="hf-healthcare-section" id="services"><div class="hf-healthcare-section-heading"><small>HEALTHCARE SERVICES</small><h2>'+(diagnostic?"Explore diagnostic categories":clinic?"Find the right specialty pathway":tele?"Explore digital care services":"Explore hospital services")+'</h2><p>Clear information helps patients understand available services and the next step.</p></div><div class="hf-healthcare-service-grid">'+services+'</div><div class="hf-healthcare-category-grid">'+categories+'</div></section>';
