  const appt='<section class="hf-healthcare-appointment-band" id="appointment"><div><small>YOUR NEXT STEP</small><h2>'+(diagnostic?"Plan your diagnostic visit.":clinic?"Let's plan your next visit.":tele?"Start with a simple request.":"Need help planning a visit?")+'</h2><p>Send a non-urgent request. The provider must confirm availability and appointment time.</p></div><a class="hf-healthcare-btn light" href="./website-builder.html?template='+encodeURIComponent(t.key)+'">Configure appointment details ↗</a></section>';
