  return '<div class="hf-healthcare hf-healthcare--telehealth"><div class="hf-healthcare-topline">DIGITAL HEALTHCARE · REMOTE CARE · PRIVACY & SUPPORT</div>'+header+'<section class="hf-healthcare-tele-hero" id="top"><div class="hf-healthcare-copy"><small>CARE, CONNECTED AROUND YOU</small><h1>'+esc(t.heroTitle)+'</h1><p>'+esc(t.heroText)+'</p><div class="hf-healthcare-actions"><a class="hf-healthcare-btn" href="#appointment">Request a consultation</a><a class="hf-healthcare-text-link" href="#how-it-works">How it works ↗</a></div><div class="hf-healthcare-tele-note">Remote consultations and patient portals require separate provider integrations.</div></div><div class="hf-healthcare-tele-art">'+image+'<div class="hf-healthcare-device-card"><span>CONSULTATION REQUEST</span><b>Request received</b><small>Await confirmation from the care team</small></div></div></section><section class="hf-healthcare-steps" id="how-it-works"><div><small>HOW IT WORKS</small><h2>A clear path from request to confirmation.</h2></div><div class="hf-healthcare-step-grid"><article><b>01</b><h3>Explore care options</h3><p>Review categories configured by the operator.</p></article><article><b>02</b><h3>Send a request</h3><p>Share contact and scheduling details without medical history.</p></article><article><b>03</b><h3>Wait for confirmation</h3><p>The care team confirms eligibility, availability and channel.</p></article></div></section>'+section+'<section class="hf-healthcare-privacy-band"><div><small>PRIVACY BY DESIGN</small><h2>Only collect what the request needs.</h2><p>General contact forms should not ask for symptoms, diagnoses or medical records. Use a separately approved patient system for clinical information.</p></div><div class="hf-healthcare-privacy-points"><span>Minimal contact details</span><span>Clear confirmation steps</span><span>Operator-managed privacy notice</span></div></section>'+appt+note+'</div>';
